mapper.select:
select notice_id, title, content, created_at, is_pinned, admin_id, type, updated_at
from notice
where notice_id = #{noticeId}

mapper.update:
update notice
set is_pinned = 1 - is_pinned
where notice_id = #{noticeId}

update notice
set deleted = 1, updated_at = now()
where notice_id = #{noticeId}

mapper.select:
select n.notice_id, n.title, n.content, date_format(n.created_at, '%Y.%m.%d') as created_at, n.is_pinned, n.type, n.admin_id, n.updated_at, u.nickname from notice n left join user u on u.user_id = n.admin_id where (n.deleted = 0 or n.deleted is null) and (n.is_pinned = 0 or n.is_pinned is null)
and n.type = #{type}
and (n.title like concat('%', #{keyword}, '%') or n.content like concat('%', #{keyword}, '%') or u.nickname like concat('%', #{keyword}, '%'))
order by n.notice_id desc limit #{row},#{limit}

select count(*) from notice n left join user u on u.user_id = n.admin_id where (n.deleted = 0 or n.deleted is null) and (n.is_pinned = 0 or n.is_pinned is null)
and n.type = #{type}
and (n.title like concat('%', #{keyword}, '%') or n.content like concat('%', #{keyword}, '%') or u.nickname like concat('%', #{keyword}, '%'))

select n.notice_id,n.title,n.content,date_format(n.created_at,'%Y.%m.%d') as created_at,n.admin_id,n.type,date_format(n.updated_at,'%Y.%m.%d') as updated_at,n.deleted,u.nickname
from notice n left join user u on u.user_id = n.admin_id
where n.notice_id=#{noticeId}
